// RISQUES — /lib/polices.mjs
//
// Polices embarquees pour la generation du PDF cote serveur.
//
// POURQUOI DES SUBSTITUTS ET NON LES POLICES DE LA CHARTE
// La charte FIDAL v2.2 prescrit Georgia et Segoe UI. Ces deux polices sont
// PROPRIETAIRES (Microsoft) : les embarquer dans le depot equivaudrait a les
// redistribuer, ce que leur licence interdit, meme si elles sont installees sur
// tous les postes du cabinet. Les substituts retenus sont libres et calques sur
// les originaux :
//   Georgia  -> Gelasio    (SIL OFL, metriques compatibles, concu pour cela)
//   Segoe UI -> Open Sans  (SIL OFL, sans humaniste tres proche)
// Meme convention que Carlito pour Calibri dans TRENTE.
//
// POURQUOI DU BASE64 ET NON DES FICHIERS TTF
// Le tracage de dependances de Vercel suit les IMPORTS, non les acces au systeme
// de fichiers : un TTF lu par fs.readFileSync ne serait pas embarque dans la
// fonction deployee. Encode en module, il l'est necessairement.
//
// Chargement : import { police } from '../lib/polices.mjs'
//              const octets = police('GELASIO_REGULAR');

// Gelasio Regular — substitut metrique de Georgia (SIL OFL) — 147572 octets
const GELASIO_REGULAR = '';

// Gelasio Bold — 148380 octets
const GELASIO_BOLD = '';

// Open Sans Regular — substitut sans-serif de Segoe UI (SIL OFL) — 147528 octets
const SANS_REGULAR = '';

// Open Sans Bold — 147264 octets
const SANS_BOLD = '';

const CATALOGUE = { GELASIO_REGULAR, GELASIO_BOLD, SANS_REGULAR, SANS_BOLD };

export function police(nom) {
  const b64 = CATALOGUE[nom];
  if (!b64) throw new Error(`Police inconnue : ${nom}. Disponibles : ${Object.keys(CATALOGUE).join(', ')}`);
  return Uint8Array.from(Buffer.from(b64, 'base64'));
}

export const POLICES_DISPONIBLES = Object.keys(CATALOGUE);
